insert into public.trivia_questions (sort_key, question, choices, answer, reference, explanation) values
(1, 'Where did people try to build a tower that reached to heaven?', array['Bethel', 'Babel', 'Jericho', 'Nineveh'], 1, 'Genesis 11:9', 'God confused their language there, so the place was called Babel.'),
(2, 'According to John, what kind of branches did the crowd carry to welcome Jesus?', array['Willow branches', 'Fig leaves', 'Palm branches', 'Cedar branches'], 2, 'John 12:13', 'They cried, "Hosanna! Blessed is the King of Israel."'),
(3, 'When Israel fought Amalek, whose hands were held up so Israel would win?', array['Moses'' hands', 'Joshua''s hands', 'Saul''s hands', 'Gideon''s hands'], 0, 'Exodus 17:12', 'Aaron and Hur held up Moses'' hands until the sun went down.'),
(4, 'What did Peter, Andrew, James, and John do for work?', array['They were fishermen', 'They were carpenters', 'They were shepherds', 'They were tentmakers'], 0, 'Matthew 4:18', 'Jesus found them casting nets into the Sea of Galilee.'),
(5, 'When God asked, "Whom shall I send?", what did Isaiah answer?', array['"Who am I?"', '"I am too young"', '"Speak, Lord"', '"Here am I; send me"'], 3, 'Isaiah 6:8', 'Isaiah answered right after seeing the Lord high and lifted up.'),
(6, 'On the night Jesus was born, to whom did an angel announce the news?', array['The wise men', 'King Herod', 'The priests in the temple', 'Shepherds in the fields'], 3, 'Luke 2:8-11', 'The angel said, "Unto you is born this day in the city of David a Saviour."'),
(7, 'Two disciples walked with the risen Jesus on the road to which village?', array['Nain', 'Emmaus', 'Cana', 'Bethany'], 1, 'Luke 24:13', 'They didn''t recognize Him until He broke bread with them.'),
(8, 'Which prophet was swallowed by a great fish?', array['Micah', 'Amos', 'Jeremiah', 'Jonah'], 3, 'Jonah 1:17', 'The LORD prepared a great fish to swallow Jonah.'),
(9, 'Who explained the meaning of Pharaoh''s dreams?', array['Moses', 'Joseph', 'Daniel', 'Aaron'], 1, 'Genesis 41:15-16', 'Joseph told Pharaoh the answer comes from God, not from him.'),
(10, 'Who lost almost everything but said, "The Lord gave, and the Lord has taken away"?', array['Jonah', 'Jeremiah', 'Job', 'Joseph'], 2, 'Job 1:21', 'Job worshiped and said, "Blessed be the name of the LORD."'),
(11, 'Where was baby Moses hidden?', array['In a cave', 'In a shepherd''s tent', 'In a basket among the reeds of the river', 'In a well'], 2, 'Exodus 2:3', 'His mother put him in a basket of bulrushes among the reeds by the river.'),
(12, 'In which river was Jesus baptized?', array['The Jordan', 'The Euphrates', 'The Nile', 'The Jabbok'], 0, 'Matthew 3:13', 'John was baptizing in the Jordan River.'),
(13, 'What gifts did the wise men bring?', array['A lamb, a dove, and grain', 'Gold, silver, and bronze', 'Bread, wine, and oil', 'Gold, frankincense, and myrrh'], 3, 'Matthew 2:11', 'They worshiped Him and opened their treasures.'),
(14, 'Which prophet was thrown into a den of lions?', array['Jeremiah', 'Ezekiel', 'Elisha', 'Daniel'], 3, 'Daniel 6:16', 'Daniel kept praying to God, and God shut the lions'' mouths.'),
(15, 'At the Last Supper, what did Jesus wash?', array['The cups', 'Their hands', 'The disciples'' feet', 'The table'], 2, 'John 13:5', 'He did it to show them how to serve one another.'),
(16, 'How long had the woman who touched Jesus'' garment been sick?', array['12 years', '38 years', '3 years', '7 years'], 0, 'Mark 5:25', 'She was healed when she touched His clothes, and Jesus said her faith had made her well.'),
(17, 'On which mountain did Elijah face the prophets of Baal?', array['Mount Zion', 'Mount Sinai', 'Mount Carmel', 'Mount Hermon'], 2, '1 Kings 18:19', 'Elijah called all Israel and the prophets of Baal to Mount Carmel.'),
(18, 'Who sold his birthright for a bowl of stew?', array['Ishmael', 'Reuben', 'Jacob', 'Esau'], 3, 'Genesis 25:33-34', 'Esau traded his birthright to Jacob for bread and lentil stew.'),
(19, 'Who saw the risen Jesus outside the tomb and thought He was the gardener?', array['Martha', 'John', 'Peter', 'Mary Magdalene'], 3, 'John 20:15-16', 'When Jesus said her name, "Mary," she knew Him.'),
(20, 'Where in the Bible does Jesus teach the prayer that begins "Our Father in heaven"?', array['Psalm 23', 'Matthew 6', 'John 17', 'Genesis 1'], 1, 'Matthew 6:9', 'It''s also found in Luke 11.'),
(21, 'In which town did Jesus grow up?', array['Bethlehem', 'Bethany', 'Jericho', 'Nazareth'], 3, 'Luke 2:39-40', 'That''s why He was called Jesus of Nazareth.'),
(22, 'Which priest could not speak until his son John was born?', array['Caiaphas', 'Zechariah', 'Eli', 'Simeon'], 1, 'Luke 1:13-20', 'Zechariah doubted the angel''s message, so he could not speak until it came true. Some Bibles spell it Zacharias.'),
(23, '"Blessed are the meek, for they shall inherit the ____."', array['Earth', 'Riches', 'A crown', 'Heavens'], 0, 'Matthew 5:5', 'Jesus echoed Psalm 37:11.'),
(24, 'Which woman prayed for a son and then gave him to serve the Lord?', array['Hannah', 'Sarah', 'Elizabeth', 'Rachel'], 0, '1 Samuel 1:20', 'Hannah named her son Samuel, because she had asked him of the LORD.'),
(25, 'Jesus said, "I am the light of the ____."', array['World', 'Church', 'Nations', 'Heavens'], 0, 'John 8:12', 'Whoever follows Him will not walk in darkness.'),
(26, 'Which king tried to kill the baby Jesus?', array['Caesar Augustus', 'Pilate', 'Herod', 'Agrippa'], 2, 'Matthew 2:13', 'An angel warned Joseph in a dream to flee to Egypt.'),
(27, 'Which woman, known for her good works, did Peter raise from the dead in Joppa?', array['Lydia', 'Tabitha, also called Dorcas', 'Priscilla', 'Rhoda'], 1, 'Acts 9:36-40', 'Peter knelt, prayed, and said, "Tabitha, arise."'),
(28, 'Who explained Isaiah to an Ethiopian official riding in a chariot?', array['Peter', 'Paul', 'Stephen', 'Philip'], 3, 'Acts 8:30-35', 'Philip told him the good news about Jesus, and the man was baptized.'),
(29, 'Into which country was Joseph taken as a slave?', array['Persia', 'Babylon', 'Egypt', 'Assyria'], 2, 'Genesis 37:36', 'The traders sold Joseph in Egypt to Potiphar.'),
(30, 'For how many days did the risen Jesus appear to His followers before He went up to heaven?', array['40', '50', '3', '7'], 0, 'Acts 1:3', 'He spoke with them about the kingdom of God.'),
(31, 'Who brought food to Elijah by the brook?', array['Eagles', 'Ravens', 'Doves', 'Sparrows'], 1, '1 Kings 17:6', 'Ravens brought him bread and meat morning and evening.'),
(32, 'What was the first miracle Jesus did?', array['Turning water into wine', 'Healing a blind man', 'Walking on water', 'Feeding 5,000 people'], 0, 'John 2:11', 'It happened at a wedding in Cana of Galilee.'),
(33, 'What did Jacob see in his dream at Bethel?', array['A great statue', 'A burning bush', 'Seven cows', 'A ladder reaching to heaven'], 3, 'Genesis 28:12', 'Jacob dreamed of a ladder reaching to heaven with angels going up and down on it.'),
(34, '"A soft answer turns away ____."', array['Trouble', 'Friends', 'Questions', 'Wrath'], 3, 'Proverbs 15:1', 'A gentle answer calms anger, but harsh words stir it up.'),
(35, 'Psalm 23 begins, "The Lord is my..." what?', array['Shepherd', 'Rock', 'Light', 'King'], 0, 'Psalms 23:1', '"The LORD is my shepherd; I shall not want."'),
(36, 'What new name did God give Jacob?', array['Judah', 'Israel', 'Abraham', 'Joseph'], 1, 'Genesis 32:28', 'After Jacob wrestled through the night, God renamed him Israel.'),
(37, 'Which queen visited Solomon to test him with hard questions?', array['The Queen of Sheba', 'Queen Jezebel', 'Queen Esther', 'Queen Vashti'], 0, '1 Kings 10:1', 'She heard of his fame and came with hard questions.'),
(38, 'What did Moses put on a pole so people bitten by snakes could look at it and live?', array['A golden calf', 'The ark of the covenant', 'A bronze serpent', 'A lamp'], 2, 'Numbers 21:9', 'Anyone who looked at the bronze serpent lived. Jesus pointed back to this in John 3:14.'),
(39, 'Jesus said, "I am the way, the truth, and the ____."', array['Life', 'Light', 'Vine', 'Door'], 0, 'John 14:6', '"No man cometh unto the Father, but by me."'),
(40, 'Where did Jesus turn water into wine?', array['Bethany', 'Capernaum', 'Cana', 'Nain'], 2, 'John 2:1-11', 'It was at a wedding feast in Cana of Galilee.'),
(41, 'What was Joseph''s trade?', array['Tentmaker', 'Fisherman', 'Shepherd', 'Carpenter'], 3, 'Matthew 13:55', 'People asked, "Is not this the carpenter''s son?"'),
(42, '"The wages of sin is death, but the gift of God is ____."', array['Peace', 'Forgiveness', 'Wisdom', 'Eternal life'], 3, 'Romans 6:23', 'Eternal life comes through Jesus Christ our Lord.'),
(43, 'Which giant did David defeat?', array['Og', 'Anak', 'Sihon', 'Goliath'], 3, '1 Samuel 17:4', 'Goliath of Gath was over nine feet tall.'),
(44, 'What did Jesus ride into Jerusalem?', array['A camel', 'A horse', 'A chariot', 'A donkey'], 3, 'Matthew 21:7', 'This fulfilled Zechariah 9:9.'),
(45, 'About how many people were added to the church on the day of Pentecost?', array['500', '120', '3,000', '5,000'], 2, 'Acts 2:41', 'Those who received Peter''s word were baptized.'),
(46, 'Whom did Isaac marry?', array['Rebekah', 'Rachel', 'Leah', 'Sarah'], 0, 'Genesis 24:67', 'Isaac took Rebekah as his wife, and he loved her.'),
(47, 'In the parable of the lost sheep, how many sheep did the shepherd leave to find the one?', array['49', '9', '100', '99'], 3, 'Luke 15:4', 'There is joy in heaven over one sinner who repents.'),
(48, 'What was the last plague on Egypt?', array['Locusts', 'The death of the firstborn', 'Darkness', 'Frogs'], 1, 'Exodus 12:29', 'At midnight the LORD struck down the firstborn in the land of Egypt.'),
(49, '"I can do all things through Christ who ____ me."', array['Saves', 'Calls', 'Strengthens', 'Loves'], 2, 'Philippians 4:13', 'Paul wrote this about learning to be content in every situation.'),
(50, 'Paul called which young man "my own son in the faith"?', array['Silas', 'Demas', 'Apollos', 'Timothy'], 3, '1 Timothy 1:2', 'Paul wrote two letters to Timothy.'),
(51, 'What food did God send from heaven each morning in the wilderness?', array['Honeycomb', 'Figs', 'Manna', 'Barley bread'], 2, 'Exodus 16:31', 'It was white like coriander seed and tasted like wafers made with honey.'),
(52, 'What did God provide on the mountain in place of Isaac?', array['A lamb', 'A dove', 'A ram', 'A goat'], 2, 'Genesis 22:13', 'Abraham saw a ram caught in a thicket and offered it instead of his son.'),
(53, 'Who led Israel into the Promised Land after Moses died?', array['Caleb', 'Aaron', 'Joshua', 'Gideon'], 2, 'Joshua 1:1-2', 'God told Joshua to lead the people across the Jordan.'),
(54, 'Who climbed a tree to see Jesus?', array['Matthew', 'Bartimaeus', 'Nicodemus', 'Zacchaeus'], 3, 'Luke 19:2-4', 'Zacchaeus was short, so he climbed a sycamore tree.'),
(55, 'Jesus told His disciples to go and make disciples of all what?', array['Families', 'Cities', 'Synagogues', 'Nations'], 3, 'Matthew 28:19', 'This is often called the Great Commission.'),
(56, 'Who raised Esther as his own daughter?', array['King Ahasuerus', 'Her cousin Mordecai', 'Haman', 'Hegai'], 1, 'Esther 2:7', 'When her parents died, Mordecai took her as his own daughter.'),
(57, 'Isaiah said a virgin would have a son and call His name what?', array['David', 'Samuel', 'Immanuel', 'Elijah'], 2, 'Isaiah 7:14', 'Immanuel means "God with us" (Matthew 1:23).'),
(58, 'Who was chosen to speak for Moses?', array['Caleb', 'Joshua', 'His brother Aaron', 'Jethro'], 2, 'Exodus 4:14', 'God said Aaron, Moses'' brother, could speak well and would speak for him.'),
(59, 'Which prisoner was set free instead of Jesus?', array['Lazarus', 'Simon', 'Malchus', 'Barabbas'], 3, 'Matthew 27:26', 'The crowd asked for Barabbas to be released.'),
(60, 'How was Elijah taken up to heaven?', array['On the back of an eagle', 'On a cloud', 'Up a ladder', 'By a whirlwind'], 3, '2 Kings 2:11', 'A chariot of fire appeared, and Elijah went up by a whirlwind into heaven.'),
(61, 'Who was made to carry Jesus'' cross?', array['Simon Peter', 'Simon of Cyrene', 'Joseph of Arimathea', 'John'], 1, 'Matthew 27:32', 'Soldiers found a man of Cyrene named Simon and made him carry it.'),
(62, 'What special gift did Jacob give his son Joseph?', array['A donkey', 'A coat of many colors', 'A gold ring', 'A sword'], 1, 'Genesis 37:3', 'Jacob loved Joseph and made him a coat of many colors.'),
(63, 'In Jesus'' story, the wise man built his house on what?', array['The sand', 'A hill', 'A riverbank', 'The rock'], 3, 'Matthew 7:24', 'The wise man hears Jesus'' words and does them.'),
(64, 'Who found baby Moses in the river?', array['An Egyptian soldier', 'Pharaoh''s daughter', 'A shepherd', 'Pharaoh''s wife'], 1, 'Exodus 2:5-6', 'Pharaoh''s daughter came down to bathe, saw the basket, and had pity on the baby.'),
(65, 'Jesus said, "I am the good ____."', array['Teacher', 'King', 'Servant', 'Shepherd'], 3, 'John 10:11', 'The good shepherd gives His life for the sheep.'),
(66, 'God told Abram his descendants would be as many as what?', array['The drops of rain', 'The fish in the sea', 'The stars in the sky', 'The leaves on the trees'], 2, 'Genesis 15:5', 'God told Abram to look up and count the stars, if he could.'),
(67, 'When Jesus was 12, where did Mary and Joseph find Him?', array['In the temple', 'In Bethlehem', 'In a carpenter''s shop', 'By the Jordan River'], 0, 'Luke 2:46', 'He was sitting among the teachers, listening and asking questions.'),
(68, 'Who killed his brother Abel?', array['Cain', 'Esau', 'Seth', 'Lamech'], 0, 'Genesis 4:8', 'Cain rose up against his brother Abel in the field and killed him.'),
(69, 'What did the Israelites put on their doorposts at the first Passover?', array['Water', 'Ashes', 'Olive oil', 'The blood of a lamb'], 3, 'Exodus 12:7', 'They put the lamb''s blood on the doorposts, and the LORD passed over those houses.'),
(70, 'Which servant girl was so excited to hear Peter at the door that she forgot to open it?', array['Lydia', 'Rhoda', 'Dorcas', 'Mary'], 1, 'Acts 12:13-14', 'An angel had just led Peter out of prison.'),
(71, 'Which man "walked with God, and he was not, for God took him"?', array['Seth', 'Methuselah', 'Enoch', 'Lamech'], 2, 'Genesis 5:24', 'Enoch walked with God, and God took him.'),
(72, 'Whose donkey spoke to him?', array['Gideon', 'Balaam', 'Samson', 'Balak'], 1, 'Numbers 22:28', 'The LORD opened the donkey''s mouth, and it spoke to Balaam.'),
(73, 'Who came to Jesus at night with questions?', array['Nicodemus', 'Zacchaeus', 'Joseph of Arimathea', 'Lazarus'], 0, 'John 3:1-2', 'Nicodemus was a Pharisee and a ruler of the Jews.'),
(74, 'Which chapter of the Bible is often called the love chapter?', array['Romans 8', 'John 3', '1 Corinthians 13', 'Psalm 23'], 2, '1 Corinthians 13:4', '"Love suffers long and is kind." Older Bibles use the word charity.'),
(75, 'In the book of Acts, who was the first believer killed for his faith?', array['Stephen', 'Peter', 'Philip', 'James'], 0, 'Acts 7:59-60', 'As he was stoned, Stephen prayed for the people killing him.'),
(76, 'While Martha was busy serving, what was Mary doing?', array['Sleeping', 'Sitting at Jesus'' feet, listening', 'Going to the market', 'Cooking in the kitchen'], 1, 'Luke 10:39', 'Jesus said Mary had chosen the good part.'),
(77, 'What is the first fruit of the Spirit listed in Galatians 5:22?', array['Love', 'Joy', 'Faith', 'Peace'], 0, 'Galatians 5:22', 'Love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control.'),
(78, 'How many times did Jesus tell Peter to forgive?', array['Twelve times', 'Seven times', 'Forty times', 'Seventy times seven'], 3, 'Matthew 18:22', 'Some translations say seventy-seven times. Either way, Jesus was teaching that forgiveness has no limit.'),
(79, 'Which king began to reign at eight years old, and during his reign the Book of the Law was found?', array['Uzziah', 'Manasseh', 'Hezekiah', 'Josiah'], 3, '2 Kings 22:1', 'Josiah did what was right, and the Book of the Law was found during his reign.'),
(80, 'What was the name of Abraham''s wife?', array['Rachel', 'Leah', 'Rebekah', 'Sarah'], 3, 'Genesis 17:15', 'God changed Sarai''s name to Sarah.'),
(81, 'How many men did the king see walking in the fiery furnace?', array['4', '2', '3', '7'], 0, 'Daniel 3:25', 'The king said the fourth looked like the Son of God.'),
(82, 'Which wicked queen threatened Elijah''s life?', array['Vashti', 'Michal', 'Delilah', 'Jezebel'], 3, '1 Kings 19:1-2', 'Jezebel sent word that she would kill Elijah, so he ran for his life.'),
(83, 'How many times did Peter deny knowing Jesus?', array['3', '1', '12', '7'], 0, 'Matthew 26:34', 'Jesus told him it would happen before the rooster crowed.'),
(84, 'In which town was Jesus born?', array['Jerusalem', 'Nazareth', 'Capernaum', 'Bethlehem'], 3, 'Matthew 2:1', 'Jesus was born in Bethlehem of Judea, the town of David.'),
(85, 'Who asked Pilate for Jesus'' body and laid it in his own new tomb?', array['Zacchaeus', 'Lazarus', 'Peter', 'Joseph of Arimathea'], 3, 'Matthew 27:57-60', 'Joseph wrapped the body in clean linen and rolled a great stone over the door.'),
(86, 'What sign did God give that He would never again flood the whole earth?', array['An olive tree', 'A star', 'A rainbow', 'A dove'], 2, 'Genesis 9:13', 'God set His bow in the clouds as the sign of His covenant.'),
(87, '"God is ____." (1 John 4:8)', array['Great', 'Holy', 'Light', 'Love'], 3, '1 John 4:8', 'Whoever does not love does not know God.'),
(88, 'Which son of David became king after him?', array['Absalom', 'Amnon', 'Solomon', 'Adonijah'], 2, '1 Kings 1:39', 'Zadok the priest anointed Solomon, and the people shouted, "God save King Solomon!"'),
(89, '"Trust in the Lord with all your heart, and lean not on your own ____."', array['Understanding', 'Strength', 'Feelings', 'Plans'], 0, 'Proverbs 3:5', 'Proverbs 3:6 goes on: in all your ways acknowledge Him, and He will direct your paths.'),
(90, 'How old was Abraham when Isaac was born?', array['120', '75', '90', '100'], 3, 'Genesis 21:5', 'Abraham was a hundred years old when Isaac was born.'),
(91, 'What did Solomon build in Jerusalem?', array['The Tower of Babel', 'Noah''s ark', 'The tabernacle', 'The temple'], 3, '1 Kings 6:1', 'Solomon built the house of the LORD, 480 years after Israel left Egypt.'),
(92, 'What appeared over the believers'' heads on the day of Pentecost?', array['Doves', 'Crowns of gold', 'Halos of light', 'Tongues like fire'], 3, 'Acts 2:3-4', 'They were all filled with the Holy Spirit.'),
(93, 'Who lived longer than anyone else in the Bible?', array['Adam', 'Enoch', 'Methuselah', 'Noah'], 2, 'Genesis 5:27', 'Methuselah lived 969 years.'),
(94, 'What fell from heaven onto Elijah''s altar on Mount Carmel?', array['Fire', 'Hail', 'Rain', 'Manna'], 0, '1 Kings 18:38', 'The fire of the LORD fell and burned up the sacrifice, the wood, the stones, and even the water.'),
(95, 'What did Paul make for a living?', array['Tents', 'Fishing nets', 'Furniture', 'Pottery'], 0, 'Acts 18:3', 'He worked with Aquila and Priscilla, who were also tentmakers.'),
(96, 'Which commandment is the first with a promise attached?', array['Remember the Sabbath day', 'Do not lie', 'Do not steal', 'Honor your father and mother'], 3, 'Ephesians 6:2-3', 'Honor your father and mother, that it may be well with you.'),
(97, 'Who led the people in rebuilding the walls of Jerusalem?', array['Nehemiah', 'Zerubbabel', 'Ezra', 'Daniel'], 0, 'Nehemiah 2:17-18', 'Nehemiah said, "Let us build up the wall of Jerusalem," and the people started the work.'),
(98, 'Which chapter is known for listing many heroes of faith?', array['Hebrews 11', 'James 2', 'Romans 12', 'Psalm 119'], 0, 'Hebrews 11:4', 'Abel, Enoch, Noah, Abraham, Sarah, Moses, Rahab, and more.'),
(99, 'Who was the high priest when Jesus was put on trial?', array['Eli', 'Zadok', 'Gamaliel', 'Caiaphas'], 3, 'Matthew 26:57', 'Jesus was led to Caiaphas, where the scribes and elders had gathered.'),
(100, 'Which seller of purple cloth believed when Paul preached in Philippi?', array['Phoebe', 'Lydia', 'Priscilla', 'Dorcas'], 1, 'Acts 16:14', 'The Lord opened her heart.'),
(101, 'Isaiah says those who wait on the Lord will mount up with wings like what?', array['Sparrows', 'Angels', 'Eagles', 'Doves'], 2, 'Isaiah 40:31', 'They shall run and not be weary, they shall walk and not faint.'),
(102, 'Which prophet saw a valley of dry bones come to life?', array['Ezekiel', 'Daniel', 'Jeremiah', 'Hosea'], 0, 'Ezekiel 37:1-3', 'God asked Ezekiel, "Can these bones live?"'),
(103, 'Whom did Ruth marry?', array['Jesse', 'Obed', 'Boaz', 'Elimelech'], 2, 'Ruth 4:13', 'Boaz married Ruth, and she became the great-grandmother of King David.'),
(104, 'Of faith, hope, and love, which does Paul call the greatest?', array['Hope', 'Faith', 'They are all equal', 'Love'], 3, '1 Corinthians 13:13', 'Older Bibles say charity, which means love.'),
(105, 'On which mountain did God give Moses the two tablets of the law?', array['Mount Zion', 'Mount Carmel', 'Mount of Olives', 'Mount Sinai'], 3, 'Exodus 31:18', 'God gave Moses two tablets of stone on Mount Sinai, written with His finger.'),
(106, 'At whose feet did the men stoning Stephen lay their coats?', array['Barnabas''s', 'Saul''s', 'Herod''s', 'Gamaliel''s'], 1, 'Acts 7:58', 'This Saul later became the apostle Paul.'),
(107, 'What did Gideon lay out when he asked God for a sign?', array['A fleece of wool', 'A stone', 'A basket', 'A lamp'], 0, 'Judges 6:37', 'Gideon asked for dew on the fleece and dry ground around it.'),
(108, 'According to Proverbs, what is the beginning of knowledge?', array['Great wealth', 'Growing old', 'Reading many books', 'The fear of the Lord'], 3, 'Proverbs 1:7', 'Knowing God rightly is where true knowledge starts.'),
(109, 'How many days and nights did it rain during the flood?', array['100', '12', '7', '40'], 3, 'Genesis 7:12', 'The rain fell on the earth forty days and forty nights.'),
(110, 'Who asked for a double portion of Elijah''s spirit?', array['Elisha', 'Obadiah', 'Jonah', 'Gehazi'], 0, '2 Kings 2:9', 'Elisha asked for a double portion, and he saw Elijah taken up.'),
(111, 'What did Jesus call the first and great commandment?', array['Do not kill', 'Honor your father and mother', 'Love the Lord your God with all your heart, soul, and mind', 'Keep the Sabbath day holy'], 2, 'Matthew 22:37-38', 'And the second is like it: love your neighbor as yourself.'),
(112, 'On the road to which city did Saul meet the risen Jesus?', array['Jericho', 'Damascus', 'Emmaus', 'Jerusalem'], 1, 'Acts 9:3', 'A light from heaven flashed around him.'),
(113, 'Who hid the two Israelite spies in Jericho?', array['Ruth', 'Deborah', 'Delilah', 'Rahab'], 3, 'Joshua 2:1', 'Rahab hid the spies on her roof and was saved when Jericho fell.'),
(114, 'What did Pharaoh''s dream of seven thin cows mean?', array['Seven kings', 'Seven plagues', 'Seven years of famine', 'Seven wars'], 2, 'Genesis 41:27', 'The seven thin cows stood for seven years of famine.'),
(115, 'Who were praying and singing in prison at midnight when an earthquake shook the doors open?', array['Stephen and Philip', 'Peter and John', 'Paul and Silas', 'Paul and Barnabas'], 2, 'Acts 16:25-26', 'The jailer and his whole family believed that night.'),
(116, 'Isaiah 9:6 calls the coming child Wonderful Counselor, Mighty God, Everlasting Father, and what?', array['Son of David', 'King of Kings', 'Lamb of God', 'Prince of Peace'], 3, 'Isaiah 9:6', '"For unto us a child is born, unto us a son is given."'),
(117, 'How many years did Israel wander in the wilderness?', array['70', '7', '40', '12'], 2, 'Numbers 14:33-34', 'One year for each of the forty days the spies explored the land.'),
(118, 'For how much silver did Judas agree to betray Jesus?', array['20 pieces', '10 pieces', '50 pieces', '30 pieces'], 3, 'Matthew 26:15', 'This fulfilled Zechariah 11:12.'),
(119, 'Which disciple walked on the water toward Jesus?', array['Thomas', 'John', 'Andrew', 'Peter'], 3, 'Matthew 14:29', 'When Peter looked at the wind he began to sink, and Jesus caught him.'),
(120, 'What is the shortest verse in most English Bibles?', array['"God is love."', '"Pray without ceasing."', '"Rejoice evermore."', '"Jesus wept."'], 3, 'John 11:35', 'Jesus wept at the tomb of His friend Lazarus.'),
(121, 'How many apostles did Jesus choose?', array['12', '10', '3', '7'], 0, 'Luke 6:13', 'He prayed all night, then chose twelve and named them apostles.'),
(122, 'For how much silver did Joseph''s brothers sell him?', array['50 pieces', '30 pieces', '20 pieces', '10 pieces'], 2, 'Genesis 37:28', 'They sold Joseph to traders for twenty pieces of silver.'),
(123, 'What does Paul tell us to put on to stand against the devil''s schemes?', array['Sackcloth', 'White robes', 'The whole armor of God', 'A crown of gold'], 2, 'Ephesians 6:11', 'He goes on to list the belt of truth, the shield of faith, and more.'),
(124, 'Whom did Jesus raise from the dead after four days in the tomb?', array['Dorcas', 'Jairus''s daughter', 'Lazarus', 'The widow''s son'], 2, 'John 11:39-44', 'Jesus called, "Lazarus, come forth," and he came out.'),
(125, 'What did the handwriting on the wall mean for King Belshazzar?', array['He would live a long life', 'His kingdom was finished', 'Rain was coming', 'He would have a son'], 1, 'Daniel 5:26', '"God has numbered your kingdom and finished it." Belshazzar died that night.'),
(126, 'With how many men did Gideon defeat the Midianites?', array['3,000', '300', '10,000', '32,000'], 1, 'Judges 7:7', 'God said He would save Israel with the three hundred men who lapped the water.'),
(127, 'How many people were saved in Noah''s ark?', array['12', '2', '40', '8'], 3, '1 Peter 3:20', 'Noah, his wife, their three sons, and their sons'' wives. Eight people in all.'),
(128, 'Who was the first man?', array['Abel', 'Adam', 'Seth', 'Noah'], 1, 'Genesis 2:19-20', 'God formed Adam, and Adam named all the animals.'),
(129, 'What happened to Lot''s wife when she looked back?', array['She went blind', 'She turned to stone', 'She fell asleep', 'She became a pillar of salt'], 3, 'Genesis 19:26', 'She looked back toward Sodom and became a pillar of salt.'),
(130, 'In the parable of the lost son, what did the father do when he saw his son coming home?', array['Waited at the door', 'Ran to him, hugged him, and kissed him', 'Made him a servant', 'Sent him away'], 1, 'Luke 15:20', 'His father saw him a long way off and had compassion.'),
(131, 'Which disciple was a tax collector?', array['Peter', 'Thomas', 'Matthew', 'Judas'], 2, 'Matthew 10:3', 'Jesus called Matthew from his tax booth, and he got up and followed.'),
(132, 'What was David''s job before he became king?', array['Fisherman', 'Tax collector', 'Shepherd', 'Carpenter'], 2, '1 Samuel 16:11', 'David was the youngest son, out keeping the sheep, when Samuel came.'),
(133, 'Which angel told Mary she would have a son?', array['Michael', 'Gabriel', 'Raphael', 'No angel was named'], 1, 'Luke 1:26-31', 'God sent the angel Gabriel to Mary in Nazareth.'),
(134, 'How long was Jonah inside the great fish?', array['One day', 'Seven days', 'Forty days', 'Three days and three nights'], 3, 'Jonah 1:17', 'Jesus pointed to this as a sign of His own death and resurrection (Matthew 12:40).'),
(135, 'Which Jewish woman became queen of Persia and saved her people?', array['Deborah', 'Vashti', 'Esther', 'Ruth'], 2, 'Esther 2:17', 'The king loved Esther and made her queen.'),
(136, 'In the parable, who stopped to help the man beaten by robbers?', array['A Samaritan', 'A priest', 'A Levite', 'A Roman soldier'], 0, 'Luke 10:33', 'The priest and the Levite passed by. The Samaritan had compassion.'),
(137, 'What came down on Jesus like a dove at His baptism?', array['An angel', 'A cloud', 'The Spirit of God', 'Fire'], 2, 'Matthew 3:16', 'And a voice from heaven said, "This is my beloved Son."'),
(138, 'On which day of the week did the women find the tomb empty?', array['The sixth day', 'The first day of the week', 'The second day', 'The Sabbath'], 1, 'Matthew 28:1', 'That''s why Christians gather on Sunday, the day of the resurrection.'),
(139, 'Which blind man called out, "Jesus, Son of David, have mercy on me"?', array['Zacchaeus', 'Lazarus', 'Bartimaeus', 'Malchus'], 2, 'Mark 10:46-47', 'Jesus healed him, and he followed Jesus on the road.'),
(140, 'To which city did God send Jonah to preach?', array['Jerusalem', 'Nineveh', 'Babylon', 'Tarshish'], 1, 'Jonah 1:2', 'Jonah ran toward Tarshish instead, but God brought him back.'),
(141, 'Saul is also called by what other name?', array['Stephen', 'Peter', 'Paul', 'Barnabas'], 2, 'Acts 13:9', '"Saul, (who also is called Paul)."'),
(142, 'What did the wise men follow to find Jesus?', array['An angel', 'A river', 'A star', 'A cloud'], 2, 'Matthew 2:9', 'The star went before them and stopped over the place where the child was.'),
(143, 'How many times did Naaman dip in the Jordan River to be healed?', array['7', '10', '3', '12'], 0, '2 Kings 5:14', 'After the seventh time, his skin became like a little child''s.'),
(144, '"Your word is a lamp to my feet and a ____ to my path."', array['Light', 'Map', 'Rod', 'Guide'], 0, 'Psalms 119:105', 'God''s word shows us where to step next.'),
(145, 'What was the name of the place where Jesus was crucified?', array['Emmaus', 'Golgotha', 'Bethany', 'Gethsemane'], 1, 'Matthew 27:33', 'Golgotha means "place of a skull."'),
(146, 'How did God first speak to Moses?', array['From a whirlwind', 'Through a talking donkey', 'In a dream', 'From a burning bush'], 3, 'Exodus 3:2', 'The bush was burning, but it was not burned up.'),
(147, 'Where did Mary lay baby Jesus?', array['In a bed at the inn', 'In a cradle', 'In a manger', 'In a basket'], 2, 'Luke 2:7', 'There was no room for them in the inn.'),
(148, 'What did God create on the first day?', array['The sun and moon', 'Fish and birds', 'Dry land', 'Light'], 3, 'Genesis 1:3-5', 'God said, "Let there be light," and there was light. That was the first day.'),
(149, 'Jesus told Nicodemus, "You must be born ____."', array['Again', 'Baptized', 'Forgiven', 'Humble'], 0, 'John 3:7', 'To see the kingdom of God, a person must be born again.'),
(150, 'When Jesus says, "I am Alpha and Omega," what does He mean?', array['The king and the priest', 'Light and darkness', 'Heaven and earth', 'The beginning and the end'], 3, 'Revelation 22:13', 'Alpha and Omega are the first and last letters of the Greek alphabet.'),
(151, 'Who baptized Jesus?', array['Andrew', 'Peter', 'Zechariah', 'John the Baptist'], 3, 'Matthew 3:13', 'Jesus came from Galilee to the Jordan to be baptized by John.'),
(152, 'According to John, what did Jesus say just before He gave up His spirit?', array['"Follow Me"', '"It is finished"', '"Peace, be still"', '"Father, forgive them"'], 1, 'John 19:30', 'Jesus said, "It is finished," bowed His head, and gave up His spirit.'),
(153, 'How many years did Jacob first agree to work so he could marry Rachel?', array['7', '3', '1', '12'], 0, 'Genesis 29:20', 'Jacob served seven years for Rachel, and they seemed like only a few days because he loved her.'),
(154, '"Blessed are the ____, for they shall be called children of God."', array['Peacemakers', 'Poor in spirit', 'Merciful', 'Meek'], 0, 'Matthew 5:9', 'This is one of the Beatitudes from the Sermon on the Mount.'),
(155, 'Which two spies brought back a good report of the Promised Land?', array['Moses and Aaron', 'Gideon and Barak', 'Ephraim and Manasseh', 'Joshua and Caleb'], 3, 'Numbers 14:6-8', 'Joshua and Caleb said the land was very good and the LORD would bring them in.'),
(156, 'Who was Moses'' father-in-law?', array['Jethro', 'Hur', 'Aaron', 'Laban'], 0, 'Exodus 3:1', 'Moses was keeping the flock of Jethro, his father-in-law, when God called him.'),
(157, 'Which prophet said the ruler of Israel would come from Bethlehem?', array['Malachi', 'Micah', 'Joel', 'Nahum'], 1, 'Micah 5:2', 'The chief priests quoted this verse when the wise men asked where the Christ would be born.'),
(158, 'What instrument did David play for King Saul?', array['The flute', 'The trumpet', 'The harp', 'The drum'], 2, '1 Samuel 16:23', 'When David played the harp, Saul was refreshed.'),
(159, 'Whose daughter did Jesus raise from the dead?', array['Jairus', 'Nicodemus', 'Herod', 'Zacchaeus'], 0, 'Mark 5:22-23', 'Jairus was a ruler of the synagogue.'),
(160, 'What were the names of Lazarus''s sisters?', array['Mary and Elizabeth', 'Mary and Martha', 'Rachel and Leah', 'Ruth and Naomi'], 1, 'John 11:1', 'They lived in Bethany, and Jesus loved them.'),
(161, 'Who was David''s closest friend, the son of King Saul?', array['Joab', 'Abner', 'Absalom', 'Jonathan'], 3, '1 Samuel 18:1', 'Jonathan loved David as his own soul.'),
(162, 'As Israel left Egypt, which sea did God part for them?', array['The Sea of Galilee', 'The Mediterranean Sea', 'The Red Sea', 'The Dead Sea'], 2, 'Exodus 15:4', 'Israel walked through on dry ground, and Pharaoh''s army was drowned in the Red Sea.'),
(163, 'Which woman was a prophetess and judge of Israel?', array['Ruth', 'Esther', 'Deborah', 'Hannah'], 2, 'Judges 4:4', 'Deborah judged Israel and sat under a palm tree where people came to her.'),
(164, 'What did the Israelites make and worship while Moses was on the mountain?', array['A golden calf', 'A silver eagle', 'A stone pillar', 'A golden lamb'], 0, 'Exodus 32:4', 'Aaron made a calf of gold from the people''s earrings.'),
(165, 'Jesus said He would make His disciples fishers of what?', array['Stars', 'Men', 'Sheep', 'Fish'], 1, 'Matthew 4:19', '"Follow me, and I will make you fishers of men."'),
(166, 'Micah 6:8 says the Lord requires us to do justly, love mercy, and what?', array['Fast twice a week', 'Give a tenth', 'Go to the temple', 'Walk humbly with your God'], 3, 'Micah 6:8', '"He hath shewed thee, O man, what is good."'),
(167, 'Where was John when he received the visions in the Book of Revelation?', array['On the island of Patmos', 'On a ship', 'In a Roman prison', 'In Jerusalem'], 0, 'Revelation 1:9', 'John was there for the word of God and the testimony of Jesus.'),
(168, 'Who washed his hands to claim he was innocent of Jesus'' blood?', array['Pilate', 'Caiaphas', 'Herod', 'Barabbas'], 0, 'Matthew 27:24', 'Pilate saw that a riot was starting and washed his hands before the crowd.'),
(169, 'Romans 8:28 says all things work together for good to whom?', array['Those who work hard', 'Everyone', 'Those who are rich', 'Those who love God'], 3, 'Romans 8:28', 'To those who are called according to His purpose.'),
(170, 'Jesus said faith as small as a mustard seed could do what?', array['Move a mountain', 'Build a temple', 'Stop the rain', 'Feed a city'], 0, 'Matthew 17:20', '"Nothing shall be impossible unto you."'),
(171, 'Who was Israel''s first king?', array['David', 'Saul', 'Solomon', 'Samuel'], 1, '1 Samuel 11:15', 'The people made Saul king before the LORD in Gilgal.'),
(172, 'How many times did Israel march around Jericho on the seventh day?', array['1', '3', '12', '7'], 3, 'Joshua 6:15', 'On the seventh day they marched around the city seven times.'),
(173, 'What was the secret of Samson''s strength that he told Delilah?', array['He prayed three times a day', 'No razor had ever cut his hair', 'He wore a special belt', 'He ate honey every day'], 1, 'Judges 16:17', 'Samson had been set apart to God from birth, and no razor had come on his head.'),
(174, 'How many days did Jesus fast in the wilderness?', array['12', '40', '7', '3'], 1, 'Matthew 4:2', 'Then the devil came to tempt Him, and Jesus answered with Scripture each time.'),
(175, 'What did Moses throw down that became a snake?', array['His sandal', 'His cloak', 'His staff', 'A stone'], 2, 'Exodus 4:2-3', 'God told Moses to throw his staff on the ground, and it became a serpent.'),
(176, 'In which garden did Jesus pray the night He was arrested?', array['Bethany', 'Eden', 'Gethsemane', 'Golgotha'], 2, 'Matthew 26:36', 'He prayed, "Not as I will, but as thou wilt."'),
(177, 'What did John the Baptist eat?', array['Manna', 'Figs and dates', 'Locusts and wild honey', 'Bread and fish'], 2, 'Matthew 3:4', 'He wore camel''s hair and lived in the wilderness.'),
(178, 'James says faith without works is what?', array['Dead', 'Hidden', 'Weak', 'Young'], 0, 'James 2:26', 'Real faith shows itself in how we live.'),
(179, 'Whom did God send to pray for Saul so he could see again?', array['Barnabas', 'Peter', 'Ananias', 'Silas'], 2, 'Acts 9:17', 'Something like scales fell from Saul''s eyes.'),
(180, 'When Jesus fed the 5,000, what did the boy have?', array['Twelve loaves and two fish', 'Five loaves and two fish', 'Two loaves and five fish', 'Seven loaves and three fish'], 1, 'John 6:9', 'Jesus gave thanks and fed everyone with plenty left over.'),
(181, 'What did young Samuel say when God called him in the night?', array['"Speak, for Your servant is listening"', '"Here am I, send me"', '"Who are You, Lord?"', '"I am too young"'], 0, '1 Samuel 3:10', 'Eli taught Samuel to answer this way when the LORD called.'),
(182, 'What did the dove bring back to Noah?', array['An olive leaf', 'A fig', 'A cedar twig', 'A grape vine'], 0, 'Genesis 8:11', 'The dove came back with a freshly plucked olive leaf, so Noah knew the waters had gone down.'),
(183, 'Jesus said His followers would be witnesses in Jerusalem, Judea, Samaria, and where else?', array['To the ends of the earth', 'In Egypt', 'In Babylon', 'Only in Rome'], 0, 'Acts 1:8', 'They would receive power when the Holy Spirit came upon them.'),
(184, 'When God told Solomon to ask for anything, what did he ask for?', array['An understanding heart', 'A long life', 'Great riches', 'Victory over his enemies'], 0, '1 Kings 3:9', 'Solomon asked for wisdom to judge God''s people well, and God was pleased.'),
(185, 'How long had the man at the pool of Bethesda been sick?', array['18 years', '38 years', '40 years', '12 years'], 1, 'John 5:5', 'Jesus told him, "Rise, take up thy bed, and walk."'),
(186, 'Which prophet was told, "Before I formed you in the womb I knew you"?', array['Ezekiel', 'Jeremiah', 'Amos', 'Isaiah'], 1, 'Jeremiah 1:5', 'God called Jeremiah to be a prophet to the nations before he was born.'),
(187, 'When Jesus healed ten lepers, how many came back to thank Him?', array['10', '2', '1', '5'], 2, 'Luke 17:15-17', 'The one who returned was a Samaritan.'),
(188, 'Who held the baby Jesus in the temple and said he had seen God''s salvation?', array['Gamaliel', 'Nicodemus', 'Simeon', 'Zechariah'], 2, 'Luke 2:25-30', 'God had promised Simeon he would see the Christ before he died.'),
(189, '"For all have sinned, and come short of the ____ of God."', array['Glory', 'Love', 'Law', 'Kingdom'], 0, 'Romans 3:23', 'Everyone needs God''s grace. Nobody is left out.'),
(190, 'What did Jesus say to the wind and waves when He calmed the storm?', array['"Go away"', '"Arise"', '"Peace, be still"', '"It is finished"'], 2, 'Mark 4:39', 'The wind stopped, and there was a great calm.'),
(191, 'How many stones did David choose for his sling?', array['7', '3', '1', '5'], 3, '1 Samuel 17:40', 'David chose five smooth stones from the brook.'),
(192, 'On which island was Paul shipwrecked?', array['Patmos', 'Malta', 'Crete', 'Cyprus'], 1, 'Acts 28:1', 'Older Bibles call the island Melita.'),
(193, 'Who was thrown into the fiery furnace?', array['Peter, James, and John', 'Shadrach, Meshach, and Abednego', 'Moses, Aaron, and Hur', 'Daniel and Ezekiel'], 1, 'Daniel 3:20', 'They would not bow to the king''s golden image.'),
(194, 'What does the shield of faith put out?', array['Floods of water', 'Roaring lions', 'The fiery darts of the wicked one', 'Idle words'], 2, 'Ephesians 6:16', 'Faith in God protects us from the enemy''s attacks.'),
(195, 'Whose tables did Jesus overturn in the temple?', array['The scribes''', 'The soldiers''', 'The priests''', 'The money changers'''], 3, 'Matthew 21:12', 'Jesus said, "My house shall be called the house of prayer."'),
(196, 'According to John 3:16, what do those who believe in Jesus receive?', array['A long life on earth', 'A new name', 'Great riches', 'Everlasting life'], 3, 'John 3:16', '"For God so loved the world, that he gave his only begotten Son."'),
(197, 'Jesus said, "I am the vine; you are the ____."', array['Fruit', 'Leaves', 'Branches', 'Roots'], 2, 'John 15:5', 'Apart from Him we can do nothing.'),
(198, 'Which young man fell asleep and dropped from a window while Paul preached?', array['Eutychus', 'Onesimus', 'Timothy', 'Mark'], 0, 'Acts 20:9', 'Paul went down, embraced him, and he was alive.'),
(199, 'On which day did God rest from all His work?', array['The tenth day', 'The first day', 'The seventh day', 'The sixth day'], 2, 'Genesis 2:2', 'God finished His work and rested on the seventh day.'),
(200, 'Which disciple said he would not believe until he saw the nail marks?', array['Thomas', 'Philip', 'Peter', 'Bartholomew'], 0, 'John 20:24-25', 'When he saw Jesus, Thomas said, "My Lord and my God."'),
(201, 'What happened to the walls of Jericho when the people shouted?', array['They caught fire', 'They fell down flat', 'Nothing at first', 'They sank into the ground'], 1, 'Joshua 6:20', 'The people shouted, and the wall fell down flat.'),
(202, 'Faith is the evidence of things not ____.', array['Heard', 'Done', 'Seen', 'Known'], 2, 'Hebrews 11:1', 'Hebrews 11 then lists many heroes who lived by faith.'),
(203, 'What did God use to make Eve?', array['Clay from a river', 'A branch from a tree', 'Dust from the garden', 'A rib from Adam'], 3, 'Genesis 2:21-22', 'God put Adam into a deep sleep and made the woman from one of his ribs.'),
(204, 'How many baskets of leftovers were gathered after Jesus fed the 5,000?', array['5', '7', '3', '12'], 3, 'John 6:13', 'They filled twelve baskets with the fragments.'),
(205, '"Be still, and know that I am ____."', array['God', 'King', 'faithful', 'near'], 0, 'Psalms 46:10', 'Psalm 46 is a song about God as our refuge and strength.'),
(206, 'How did Judas show the soldiers which man was Jesus?', array['With a kiss', 'By holding up a torch', 'By calling His name', 'By pointing'], 0, 'Matthew 26:48-49', 'Judas had told them, "Whomsoever I shall kiss, that same is he."'),
(207, 'Where did Jesus meet a Samaritan woman and ask her for a drink?', array['At a well', 'At the temple', 'At the river Jordan', 'At a wedding'], 0, 'John 4:6-7', 'Jesus offered her living water.'),
(208, 'Which book says, "To every thing there is a season"?', array['Ecclesiastes', 'Proverbs', 'Job', 'Psalms'], 0, 'Ecclesiastes 3:1', 'A time to be born, a time to die, a time to weep, a time to laugh.'),
(209, 'Who was the mother of John the Baptist?', array['Elizabeth', 'Mary', 'Anna', 'Hannah'], 0, 'Luke 1:13', 'The angel told Zechariah his wife Elizabeth would have a son named John.'),
(210, 'Which disciple betrayed Jesus?', array['Peter', 'Thaddaeus', 'Judas Iscariot', 'Thomas'], 2, 'Matthew 26:14-16', 'Judas went to the chief priests and agreed to hand Jesus over.'),
(211, 'Who said, "Where you go, I will go"?', array['Orpah', 'Esther', 'Naomi', 'Ruth'], 3, 'Ruth 1:16', 'Ruth told Naomi, "Your people shall be my people, and your God my God."'),
(212, 'Who betrayed Samson to the Philistines?', array['Rahab', 'Delilah', 'Jezebel', 'Michal'], 1, 'Judges 16:18', 'Delilah told the Philistines, and they paid her silver.')
